steps.script:
$o=@{state='pending'}
try{
 $p=Get-CimInstance Win32_Process -Filter 'ProcessId=51120' -ErrorAction Stop
 if(-not $p){$o.state='already_gone'}
 elseif([string]$p.CommandLine -notmatch 'C:[\\]TTiTTulares[\\]Ejecutar[.]js.*titulares --enviar'){$o.state='mismatch'}
 else{
  $d='C:\TTiTTulares\TT-Editorial-Rescue\sent'
  $amb=@(Get-ChildItem $d -Filter 'TTITTULARES_EDITORIAL_JOB_V2_*.json' -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -gt (Get-Date).AddMinutes(-10) } | ForEach-Object { Get-Content $_.FullName -Raw | ConvertFrom-Json } | Where-Object { $_.status -in @('submit_intent','confirmed') })
  if($amb.Count){$o.state='protected_send';$o.count=$amb.Count}
  else{Stop-Process -Id 51120 -Force -ErrorAction Stop;$o.state='stale_wrapper_stopped'}
 }
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
